import 'package:flutter/material.dart';

void main() => runApp(const JbrApp());

const ink = Color(0xFF151D1D), teal = Color(0xFF00696C), cyan = Color(0xFF00E5EC);
const canvas = Color(0xFFF2FBFB), muted = Color(0xFFE7F0EF), pale = Color(0xFFECF5F5);

class JbrApp extends StatelessWidget {
  const JbrApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    title: 'JBR Logistics', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: canvas, colorScheme: ColorScheme.fromSeed(seedColor: teal, primary: teal, surface: canvas), fontFamily: 'Roboto', appBarTheme: const AppBarTheme(backgroundColor: canvas, foregroundColor: ink, elevation: 0)),
    home: const LogisticsShell());
}

class Shipment {
  Shipment(this.id, this.type, this.origin, this.destination, this.status, this.date, this.amount);
  final String id, type, origin, destination, status, date, amount;
}

class LogisticsShell extends StatefulWidget {
  const LogisticsShell({super.key});
  @override State<LogisticsShell> createState() => _LogisticsShellState();
}
class _LogisticsShellState extends State<LogisticsShell> {
  int tab = 0;
  final List<Shipment> shipments = [
    Shipment('LR-98421','Express Cargo','Mumbai, MH','New Delhi, DL','In Transit','Oct 28, 2023','$1,250.00'),
    Shipment('LR-98110','Standard Freight','Boston, MA','Atlanta, GA','Upcoming','Oct 30, 2023','Payment Pending'),
    Shipment('LR-97950','Commercial Freight','Miami, FL','Dallas, TX','Delivered','Oct 22, 2023','$3,400.00'),
    Shipment('LR-97622','Part Truckload','Seattle, WA','Denver, CO','Cancelled','Oct 16, 2023','Refunded'),
  ];
  void go(int index) => setState(() => tab = index);
  @override Widget build(BuildContext context) {
    final pages = [DashboardPage(shipments: shipments, onBook: () => go(2), onBookings: () => go(1), onTrack: (id) => setState(() { tab = 3; }),), BookingsPage(shipments: shipments, onDetails: (s) => setState(() => tab = 3)), BookingPage(onConfirm: (s) { setState(() { shipments.insert(0,s); tab = 1; }); },), TrackingPage(shipment: shipments.first)];
    return Scaffold(body: SafeArea(child: pages[tab]), bottomNavigationBar: NavigationBar(height: 72, backgroundColor: canvas, selectedIndex: tab, onDestinationSelected: (i) => go(i), destinations: const [NavigationDestination(icon: Icon(Icons.home_outlined), selectedIcon: Icon(Icons.home), label: 'Home'), NavigationDestination(icon: Icon(Icons.local_shipping_outlined), selectedIcon: Icon(Icons.local_shipping), label: 'Bookings'), NavigationDestination(icon: Icon(Icons.add_circle, size: 40, color: cyan), label: 'Book'), NavigationDestination(icon: Icon(Icons.my_location_outlined), selectedIcon: Icon(Icons.my_location), label: 'Track')],), floatingActionButton: tab == 0 || tab == 1 ? FloatingActionButton(backgroundColor: cyan, foregroundColor: teal, onPressed: () => go(2), child: const Icon(Icons.add, size: 30)) : null, floatingActionButtonLocation: FloatingActionButtonLocation.centerDocked);
  }
}

